function [m] = modulo(n,N);m = rem(rem(n-1,N)+N,N)+1;% Written by Maureen Clerc and Jerome Kalifa, 1997% clerc@cmapx.polytechnique.fr, kalifa@cmapx.polytechnique.fr        %   % Part of WaveLab Version 802% Built Sunday, October 3, 1999 8:52:27 AM% This is Copyrighted Material% For Copying permissions see COPYING.m% Comments? e-mail wavelab@stat.stanford.edu%       